const config = {
  "previewFeatures": [],
  "clientVersion": "7.9.1",
  "engineVersion": "e922089b7d7502aff4249d5da3420f6fa55fc6ad",
  "activeProvider": "postgresql",
  "inlineSchema": "// MERIT Protocol — data model.\n//\n// Two rules shape this schema:\n//\n//  1. Proof records are append-only. Decision, Outcome, Proof, MerkleBatch and\n//     BlockchainAnchor rows are written once. Corrections are new Correction\n//     rows referencing the original, never edits. There is no soft-delete on a\n//     decision, because hiding a loss is the exact failure MERIT exists to stop.\n//\n//  2. Reputation is derived, never stored as truth. ReputationScore rows are a\n//     cache of a computation over verified records and can be rebuilt from them.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../lib/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ---------------------------------------------------------------- identity --\n\nmodel User {\n  id            String   @id @default(cuid())\n  email         String   @unique\n  name          String?\n  /// Solana address this account signs in with. Null for accounts created\n  /// before wallet sign-in existed, and for any created by other means.\n  walletAddress String?  @unique\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  agents  Agent[]\n  apiKeys ApiKey[]\n\n  @@index([createdAt])\n  @@map(\"users\")\n}\n\n/// A one-time challenge for wallet sign-in. The client signs the nonce with the\n/// address's private key; the server accepts the signature exactly once, so a\n/// captured message cannot be replayed. Expired and used rows are worthless and\n/// may be pruned at any time.\nmodel WalletChallenge {\n  id        String    @id @default(cuid())\n  address   String\n  nonce     String    @unique\n  expiresAt DateTime\n  usedAt    DateTime?\n  createdAt DateTime  @default(now())\n\n  @@index([address, expiresAt])\n  @@map(\"wallet_challenges\")\n}\n\n/// API credentials. Only a hash of the secret is stored; the plaintext is\n/// shown once at creation and is unrecoverable afterwards.\nmodel ApiKey {\n  id         String    @id @default(cuid())\n  userId     String\n  /// Public, non-secret identifier shown in the UI, e.g. \"mk_live_8fa2\".\n  prefix     String    @unique\n  /// SHA-256 of the full secret. Never the secret itself.\n  keyHash    String    @unique\n  name       String\n  scopes     String[]  @default([\"decisions:write\", \"outcomes:write\"])\n  lastUsedAt DateTime?\n  revokedAt  DateTime?\n  createdAt  DateTime  @default(now())\n  expiresAt  DateTime?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([keyHash])\n  @@index([revokedAt])\n  @@map(\"api_keys\")\n}\n\n// ------------------------------------------------------------------ agents --\n\nenum AgentStatus {\n  ACTIVE\n  PAUSED\n  RETIRED\n}\n\nenum VerificationStatus {\n  UNVERIFIED\n  PENDING\n  VERIFIED\n  FAILED\n}\n\nenum RiskProfile {\n  CONSERVATIVE\n  MODERATE\n  AGGRESSIVE\n}\n\nmodel Agent {\n  id            String      @id @default(cuid())\n  /// Human-facing handle, e.g. \"ALPHA-001\".\n  slug          String      @unique\n  name          String\n  description   String\n  ownerId       String\n  /// Wallet the agent signs with. Not custodial — MERIT never holds funds.\n  walletAddress String\n  venues        String[]\n  assets        String[]\n  chain         String      @default(\"solana\")\n  riskProfile   RiskProfile @default(MODERATE)\n\n  status             AgentStatus        @default(ACTIVE)\n  verificationStatus VerificationStatus @default(UNVERIFIED)\n\n  /// Seeded demo agents are flagged so the UI can label them, and so demo\n  /// performance is never presented as a live track record.\n  isDemo Boolean @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  owner            User              @relation(fields: [ownerId], references: [id], onDelete: Cascade)\n  strategies       Strategy[]\n  decisions        Decision[]\n  reputationScores ReputationScore[]\n  qualifications   Qualification[]\n  events           ProtocolEvent[]\n\n  @@index([ownerId])\n  @@index([status])\n  @@index([verificationStatus])\n  @@index([createdAt])\n  @@map(\"agents\")\n}\n\n// -------------------------------------------------------------- strategies --\n\nmodel Strategy {\n  id          String   @id @default(cuid())\n  agentId     String\n  name        String\n  description String\n  createdAt   DateTime @default(now())\n\n  agent    Agent             @relation(fields: [agentId], references: [id], onDelete: Cascade)\n  versions StrategyVersion[]\n\n  @@unique([agentId, name])\n  @@index([agentId])\n  @@map(\"strategies\")\n}\n\nenum VersionStatus {\n  ACTIVE\n  SUPERSEDED\n  RETIRED\n}\n\n/// Immutable once written. A change of strategy or model produces a new row;\n/// historical performance always points at the exact version that produced it.\nmodel StrategyVersion {\n  id          String @id @default(cuid())\n  strategyId  String\n  /// Semantic version, e.g. \"2.1.0\".\n  version     String\n  description String\n\n  model        String\n  modelVersion String\n\n  /// SHA-256 over the canonicalised configuration. Detects an undisclosed swap.\n  configHash String\n  config     Json\n\n  /// Optional signature by the agent wallet over `configHash`.\n  creatorSignature String?\n\n  status    VersionStatus @default(ACTIVE)\n  createdAt DateTime      @default(now())\n\n  strategy  Strategy   @relation(fields: [strategyId], references: [id], onDelete: Cascade)\n  decisions Decision[]\n\n  @@unique([strategyId, version])\n  @@index([strategyId])\n  @@index([configHash])\n  @@index([status])\n  @@map(\"strategy_versions\")\n}\n\n// --------------------------------------------------------------- decisions --\n\nenum DecisionAction {\n  BUY\n  SELL\n  SHORT\n  COVER\n  HOLD\n  ABSTAIN\n}\n\nenum DecisionStatus {\n  /// Committed, outcome not yet revealed.\n  OPEN\n  /// Settled at a profit.\n  SUCCESS\n  /// Settled at a loss.\n  LOSS\n  /// Window closed without settlement.\n  EXPIRED\n  /// Withdrawn before execution.\n  CANCELLED\n  /// The agent evaluated and declined to act.\n  NO_GO\n  /// The agent explicitly abstained.\n  TRADE_ABSTENTION\n}\n\n/// Append-only. There is no update path for the committed fields; see the\n/// Correction model for how mistakes are handled.\nmodel Decision {\n  id                String @id @default(cuid())\n  agentId           String\n  strategyVersionId String\n\n  asset      String\n  action     DecisionAction\n  price      Decimal        @db.Decimal(38, 12)\n  quantity   Decimal        @db.Decimal(38, 12)\n  confidence Decimal        @db.Decimal(5, 4)\n\n  /// Random per-decision salt. Keeps a published commitment from leaking the\n  /// decision to an observer before the reveal.\n  nonce String\n\n  /// SHA-256 commitment over the canonicalised decision. Written before the\n  /// outcome can be known.\n  commitmentHash String @unique\n\n  metadata Json?\n\n  status DecisionStatus @default(OPEN)\n  isDemo Boolean        @default(false)\n\n  /// When the agent made the call.\n  decidedAt   DateTime\n  /// When MERIT sealed the commitment.\n  committedAt DateTime  @default(now())\n  /// Optional deadline after which the decision expires unsettled.\n  expiresAt   DateTime?\n\n  agent           Agent           @relation(fields: [agentId], references: [id], onDelete: Cascade)\n  strategyVersion StrategyVersion @relation(fields: [strategyVersionId], references: [id])\n  outcome         Outcome?\n  proof           Proof?\n  corrections     Correction[]\n\n  @@index([agentId])\n  @@index([strategyVersionId])\n  @@index([status])\n  @@index([decidedAt])\n  @@index([committedAt])\n  @@index([commitmentHash])\n  @@index([agentId, status])\n  @@index([agentId, decidedAt])\n  @@map(\"decisions\")\n}\n\n/// Revealed result. One per decision, written once.\nmodel Outcome {\n  id         String @id @default(cuid())\n  decisionId String @unique\n\n  entryPrice Decimal @db.Decimal(38, 12)\n  exitPrice  Decimal @db.Decimal(38, 12)\n  quantity   Decimal @db.Decimal(38, 12)\n  fees       Decimal @db.Decimal(38, 12)\n  slippage   Decimal @db.Decimal(38, 12)\n\n  grossPnl    Decimal @db.Decimal(38, 12)\n  realizedPnl Decimal @db.Decimal(38, 12)\n  roi         Decimal @db.Decimal(18, 8)\n  notional    Decimal @db.Decimal(38, 12)\n\n  holdingPeriodMs BigInt\n\n  /// SHA-256 over the outcome, bound to the decision's commitment.\n  outcomeHash String @unique\n\n  settledAt DateTime\n  createdAt DateTime @default(now())\n\n  decision Decision @relation(fields: [decisionId], references: [id], onDelete: Cascade)\n\n  @@index([settledAt])\n  @@index([outcomeHash])\n  @@map(\"outcomes\")\n}\n\n/// A correction never mutates the original record — it is a new, linked event.\nmodel Correction {\n  id         String   @id @default(cuid())\n  decisionId String\n  reason     String\n  detail     Json\n  createdAt  DateTime @default(now())\n\n  decision Decision @relation(fields: [decisionId], references: [id], onDelete: Cascade)\n\n  @@index([decisionId])\n  @@map(\"corrections\")\n}\n\n// ------------------------------------------------------------------ proofs --\n\nenum BatchStatus {\n  OPEN\n  SEALED\n  ANCHORED\n  FAILED\n}\n\n/// A set of commitments hashed into one Merkle tree.\nmodel MerkleBatch {\n  id         String @id @default(cuid())\n  /// Monotonic, human-referenceable batch number.\n  sequence   Int    @unique @default(autoincrement())\n  merkleRoot String @unique\n  leafCount  Int\n\n  status BatchStatus @default(OPEN)\n\n  sealedAt  DateTime?\n  createdAt DateTime  @default(now())\n\n  proofs Proof[]\n  anchor BlockchainAnchor?\n\n  @@index([status])\n  @@index([merkleRoot])\n  @@index([createdAt])\n  @@map(\"merkle_batches\")\n}\n\n/// A decision's inclusion proof against its batch root.\nmodel Proof {\n  id         String @id @default(cuid())\n  decisionId String @unique\n  batchId    String\n\n  /// Domain-tagged leaf digest for this decision's commitment.\n  leafHash  String\n  leafIndex Int\n  /// Ordered [{ sibling, side }] path from leaf to root.\n  path      Json\n\n  createdAt DateTime @default(now())\n\n  decision Decision    @relation(fields: [decisionId], references: [id], onDelete: Cascade)\n  batch    MerkleBatch @relation(fields: [batchId], references: [id], onDelete: Cascade)\n\n  @@unique([batchId, leafIndex])\n  @@index([batchId])\n  @@index([leafHash])\n  @@map(\"proofs\")\n}\n\n/// One chain write per batch root.\nmodel BlockchainAnchor {\n  id      String @id @default(cuid())\n  batchId String @unique\n\n  network         String\n  merkleRoot      String\n  /// Null when no chain write occurred. Never populated with a synthetic value.\n  transactionHash String?\n  blockNumber     BigInt?\n  explorerUrl     String?\n\n  status AnchorStatus @default(PENDING)\n\n  anchoredAt  DateTime?\n  confirmedAt DateTime?\n  createdAt   DateTime  @default(now())\n\n  batch MerkleBatch @relation(fields: [batchId], references: [id], onDelete: Cascade)\n\n  @@index([transactionHash])\n  @@index([merkleRoot])\n  @@index([status])\n  @@index([network])\n  @@map(\"blockchain_anchors\")\n}\n\nenum AnchorStatus {\n  PENDING\n  CONFIRMED\n  FAILED\n  LOCAL_ONLY\n}\n\n// -------------------------------------------------------------- reputation --\n\n/// Cached result of the reputation computation. Rebuildable from proofs.\nmodel ReputationScore {\n  id      String @id @default(cuid())\n  agentId String\n\n  score      Decimal @db.Decimal(5, 2)\n  rawScore   Decimal @db.Decimal(5, 2)\n  confidence Decimal @db.Decimal(6, 4)\n\n  performance Decimal @db.Decimal(5, 2)\n  risk        Decimal @db.Decimal(5, 2)\n  drawdown    Decimal @db.Decimal(5, 2)\n  consistency Decimal @db.Decimal(5, 2)\n  execution   Decimal @db.Decimal(5, 2)\n  integrity   Decimal @db.Decimal(5, 2)\n\n  /// Snapshot of the metric set the score was computed from.\n  metrics Json\n\n  sampleSize    Int\n  operatingDays Int\n\n  computedAt DateTime @default(now())\n\n  agent Agent @relation(fields: [agentId], references: [id], onDelete: Cascade)\n\n  @@index([agentId])\n  @@index([computedAt])\n  @@index([agentId, computedAt])\n  @@map(\"reputation_scores\")\n}\n\nenum Tier {\n  UNVERIFIED\n  VERIFIED\n  BRONZE\n  SILVER\n  GOLD\n  ELITE\n}\n\nmodel Qualification {\n  id      String @id @default(cuid())\n  agentId String\n\n  tier     Tier\n  nextTier Tier?\n  /// Requirements still outstanding for the next tier.\n  unmet    Json\n\n  achievedAt DateTime @default(now())\n\n  agent Agent @relation(fields: [agentId], references: [id], onDelete: Cascade)\n\n  @@index([agentId])\n  @@index([tier])\n  @@index([agentId, achievedAt])\n  @@map(\"qualifications\")\n}\n\n// ------------------------------------------------------------------ events --\n\nenum EventType {\n  AGENT_CREATED\n  STRATEGY_REGISTERED\n  VERSION_CREATED\n  DECISION_COMMITTED\n  TRADE_EXECUTED\n  OUTCOME_REVEALED\n  PROOF_BATCHED\n  MERKLE_ROOT_CREATED\n  ANCHOR_CONFIRMED\n  REPUTATION_UPDATED\n  CORRECTION_RECORDED\n  VERIFICATION_REQUESTED\n}\n\n/// Append-only protocol history. Never updated, never deleted.\nmodel ProtocolEvent {\n  id      String    @id @default(cuid())\n  type    EventType\n  agentId String?\n\n  /// Entity the event refers to (decision id, batch id, …).\n  subjectId String?\n  payload   Json\n\n  createdAt DateTime @default(now())\n\n  agent Agent? @relation(fields: [agentId], references: [id], onDelete: SetNull)\n\n  @@index([type])\n  @@index([agentId])\n  @@index([subjectId])\n  @@index([createdAt])\n  @@map(\"protocol_events\")\n}\n\n/// Every third-party verification attempt, for transparency and abuse tracking.\nmodel VerificationRequest {\n  id        String   @id @default(cuid())\n  /// decision | commitment | agent | transaction\n  queryType String\n  query     String\n  valid     Boolean\n  /// Per-check results, so a failure can be explained rather than asserted.\n  checks    Json\n  createdAt DateTime @default(now())\n\n  @@index([queryType])\n  @@index([query])\n  @@index([createdAt])\n  @@map(\"verification_requests\")\n}\n\n/// Authenticated write attempts against the API.\nmodel AuditLog {\n  id         String   @id @default(cuid())\n  apiKeyId   String?\n  actorLabel String\n  action     String\n  subjectId  String?\n  ip         String?\n  userAgent  String?\n  metadata   Json?\n  createdAt  DateTime @default(now())\n\n  @@index([apiKeyId])\n  @@index([action])\n  @@index([createdAt])\n  @@map(\"audit_logs\")\n}\n"
}

